fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0L) return "0s"
    val seconds = exposureTimeNs / 1_000_000_000.0
    if (seconds >= 1.0) {
        val rounded = Math.round(seconds * 10.0) / 10.0
        return if (rounded == Math.round(rounded).toDouble()) "${rounded.toInt()}s" else "${rounded}s"
    }
    val denominator = Math.round(1.0 / seconds).toLong()
    return if (denominator <= 0L) "${seconds}s" else "1/${denominator}s"
}

