Handles normal piece movement, captures, and pawn double pushes.
Castling, en passant, promotion, and check/pin legality are NOT handled.
"""

FILES = "abcdefgh"


def _parse_fen(fen):
    parts = fen.split()
    placement = parts[0]
    turn = parts[1] if len(parts) > 1 else "w"
    board = {}
    ranks = placement.split("/")
    assert len(ranks) == 8, "FEN must have 8 ranks"
    for i, rank_str in enumerate(ranks):
        rank = 7 - i  # rank 0 = rank 1 (bottom)
        file = 0
        for ch in rank_str:
            if ch.isdigit():
                file += int(ch)
            else:
                board[(file, rank)] = ch
                file += 1
        assert file == 8, "Rank has wrong length"
    return board, turn


def _is_white(piece):
    return piece.isupper()


def _sq_name(file, rank):
    return FILES[file] + str(rank + 1)


def _parse_sq(s):
    return FILES.index(s[0]), int(s[1]) - 1


def _pseudo_moves(board, turn):
    moves = []
    white_turn = turn == "w"

    def enemy(p):
        return (p.isupper() and not white_turn) or (p.islower() and white_turn)

    def own(p):
        return (p.isupper() and white_turn) or (p.islower() and not white_turn)

    for (f, r), piece in list(board.items()):
        is_w = _is_white(piece)
        if is_w != white_turn:
            continue
        p = piece.upper()
        if p == "P":
            dir_r = 1 if is_w else -1
            start_rank = 1 if is_w else 6
            # forward push (no promotion handling)
            nr = r + dir_r
            if 0 <= nr <= 7 and (f, nr) not in board:
                # don't generate promotion moves (promotion not handled)
                if nr != (7 if is_w else 0):
                    moves.append(((f, r), (f, nr)))
                # double push
                if r == start_rank:
                    nr2 = r + 2 * dir_r
                    if 0 <= nr2 <= 7 and (f, nr2) not in board and (f, nr) not in board:
                        if nr2 != (7 if is_w else 0):
                            moves.append(((f, r), (f, nr2)))
            # captures
            if nr_ok := (0 <= r + dir_r <= 7):
                for df in (-1, 1):
                    nf = f + df
                    if 0 <= nf <= 7:
                        target = board.get((nf, r + dir_r))
                        if target and enemy(target):
                            if nr_ok and (r + dir_r) != (7 if is_w else 0):
                                moves.append(((f, r), (nf, r + dir_r)))
        elif p == "N":
            for df, dr in ((1, 2), (2, 1), (-1, 2), (-2, 1), (1, -2), (2, -1), (-1, -2), (-2, -1)):
                nf, nr = f + df, r + dr
                if 0 <= nf <= 7 and 0 <= nr <= 7:
                    target = board.get((nf, nr))
                    if not target or enemy(target):
                        moves.append(((f, r), (nf, nr)))
        elif p == "K":
            for df in (-1, 0, 1):
                for dr in (-1, 0, 1):
                    if df == 0 and dr == 0:
                        continue
                    nf, nr = f + df, r + dr
                    if 0 <= nf <= 7 and 0 <= nr <= 7:
                        target = board.get((nf, nr))
                        if not target or enemy(target):
                            moves.append(((f, r), (nf, nr)))
        else:
            dirs = []
            if p in ("R", "Q"):
                dirs += [(1, 0), (-1, 0), (0, 1), (0, -1)]
            if p in ("B", "Q"):
                dirs += [(1, 1), (1, -1), (-1, 1), (-1, -1)]
            for df, dr in dirs:
                nf, nr = f + df, r + dr
                while 0 <= nf <= 7 and 0 <= nr <= 7:
                    target = board.get((nf, nr))
                    if not target:
                        moves.append(((f, r), (nf, nr)))
                    elif enemy(target):
                        moves.append(((f, r), (nf, nr)))
                        break
