                        break
                    nf += df
                    nr += dr
    return moves


def legal_moves(fen):
    board, turn = _parse_fen(fen)
    return [_sq_name(f, r) + _sq_name(tf, tr) for (f, r), (tf, tr) in _pseudo_moves(board, turn)]


def _apply(board, turn, move):
    (f, r), (tf, tr) = move
    new = dict(board)
    piece = new.pop((f, r))
    captured = new.get((tf, tr))
    new[(tf, tr)] = piece
    new_turn = "b" if turn == "w" else "w"
    return new, new_turn, captured


def perft(fen, depth):
    if depth == 0:
        return 1
    board, turn = _parse_fen(fen)
    total = 0
    for m in _pseudo_moves(board, turn):
        new_board, new_turn, _ = _apply(board, turn, m)
        total += perft_board(new_board, new_turn, depth - 1)
    return total


def perft_board(board, turn, depth):
    if depth == 0:
        return 1
    total = 0
    for m in _pseudo_moves(board, turn):
        new_board, new_turn, _ = _apply(board, turn, m)
        total += perft_board(new_board, new_turn, depth - 1)
    return total
