"""Chess move generation.

Handles normal piece movement, captures, pawn double pushes, and castling
(with path, check, and attacked-square verification). En passant, promotion,
and full check/pin legality for non-castling moves are NOT handled.
"""

FILES = "abcdefgh"


def _parse_fen(fen):
    parts = fen.split()
    placement = parts[0]
    turn = parts[1] if len(parts) > 1 else "w"
    castling = parts[2] if len(parts) > 2 else "-"
    board = {}
    ranks = placement.split("/")
    assert len(ranks) == 8, "FEN must have 8 ranks"
    for i, rank_str in enumerate(ranks):
        rank = 7 - i  # rank 0 = rank 1 (bottom)
        file = 0
        for ch in rank_str:
            if ch.isdigit():
                file += int(ch)
            else:
                board[(file, rank)] = ch
                file += 1
        assert file == 8, "Rank has wrong length"
    return board, turn, castling


def _is_white(piece):
    return piece.isupper()


def _sq_name(file, rank):
    return FILES[file] + str(rank + 1)


def _parse_sq(s):
    return FILES.index(s[0]), int(s[1]) - 1


def _occupied(board, f, r):
    return (f, r) in board


def _attacked_by(board, f, r, by_white):
    """True if square (f, r) is attacked by any piece of the given color."""

    def color_of(p):
        return p.isupper()

    # pawns
    pawn_dir = 1 if by_white else -1
    # a by_white pawn on (f+df, r-1) attacks (f, r): check both diagonals
    for df in (-1, 1):
        pf, pr = f - df, r - pawn_dir
        if 0 <= pf <= 7 and 0 <= pr <= 7:
            p = board.get((pf, pr))
            if p and (p.upper() == "P") and color_of(p) == by_white:
                return True

    # knights
    for df, dr in ((1, 2), (2, 1), (-1, 2), (-2, 1), (1, -2), (2, -1), (-1, -2), (-2, -1)):
        pf, pr = f - df, r - dr
        if 0 <= pf <= 7 and 0 <= pr <= 7:
            p = board.get((pf, pr))
            if p and p.upper() == "N" and color_of(p) == by_white:
                return True

    # king
    for df in (-1, 0, 1):
        for dr in (-1, 0, 1):
            if df == 0 and dr == 0:
                continue
            pf, pr = f - df, r - dr
            if 0 <= pf <= 7 and 0 <= pr <= 7:
                p = board.get((pf, pr))
                if p and p.upper() == "K" and color_of(p) == by_white:
                    return True

    # sliding pieces
    for df, dr, kinds in (
        ((1, 0), ("R", "Q")), ((-1, 0), ("R", "Q")),
        ((0, 1), ("R", "Q")), ((0, -1), ("R", "Q")),
        ((1, 1), ("B", "Q")), ((1, -1), ("B", "Q")),
        ((-1, 1), ("B", "Q")), ((-1, -1), ("B", "Q")),
    ):
        pf, pr = f + df, r + dr
        while 0 <= pf <= 7 and 0 <= pr <= 7:
            p = board.get((pf, pr))
            if p:
                if p.upper() in kinds and color_of(p) == by_white:
                    return True
                break
            pf += df
            pr += dr

    return False


