            rook = board.get(rook_sq)
            if rook and rook.upper() == "R" and _is_white(rook) == white_turn:
                if (5, king_rank) not in board and (6, king_rank) not in board:
                    if not _attacked_by(board, 4, king_rank, enemy_white):
                        if not _attacked_by(board, 5, king_rank, enemy_white) and not _attacked_by(board, 6, king_rank, enemy_white):
                            moves.append((king_sq, (6, king_rank), None))

        # queenside
        if q_side in rights:
            rook_sq = (0, king_rank)
            rook = board.get(rook_sq)
            if rook and rook.upper() == "R" and _is_white(rook) == white_turn:
                if (1, king_rank) not in board and (2, king_rank) not in board and (3, king_rank) not in board:
                    if not _attacked_by(board, 4, king_rank, enemy_white):
                        if not _attacked_by(board, 3, king_rank, enemy_white) and not _attacked_by(board, 2, king_rank, enemy_white):
                            moves.append((king_sq, (2, king_rank), None))

    return moves


def _apply(board, turn, castling, ep, move):
    (f, r), (tf, tr), promo = move
    new = dict(board)
    piece = new.pop((f, r))
    new_ep = None
    captured = new.get((tf, tr))

